const segments = 10;
let origins, connections;

function setup() {
	createCanvas(windowWidth, windowHeight);
	pixelDensity(1);
	frameRate(30);
	describe("random hanging wires connected on two rotating wheels flying thru time shifting on previous state");

	const minWH = max(width, height);
	const radius = minWH * 0.2;
	const padding = radius * 1.1;
	origins = [];
	origins.push(new Origin(padding, height * 0.5, radius, segments, random(360), random(45,90)));
	origins.push(new Origin(width - padding, height * 0.5, radius, segments, random(360), random(45,90)));

	connections = [];
	for (let i = 0; i < radius * 0.1; i++) {
		const o1 = random(origins);
		const i1 = floor(random(o1.pts.length));
		const o2 = random(origins);
		const i2 = floor(random(o2.pts.length));
		connections.push(new Conn({o: o1, i: i1}, {o: o2, i: i2}));
	}

	// inital background
	background(0,0,12);
}

function mouseClicked() {
	if (mouseButton === LEFT) setup();
}

function draw() {
	// offset previous image
	let prev = get();
	const maxOff = max(width, height) * 0.05;
	const offX = noise(frameCount * 0.025) * maxOff - maxOff * 0.5;
	const offY = noise(frameCount * 0.0125) * maxOff - maxOff * 0.5;
	image(prev, offX, offY);

	// background darkblue with alpha
	background(0,0,12, 16);

	// show (partly) message in the background
	if (frameCount % 20 === 0) {
		push();
		noStroke();
		fill("white");
		textAlign(CENTER,CENTER);
		textSize(random(max(width, height) * 0.05, max(width, height) * 0.5));

		const conn = random(connections);
		const node = random() < 0.5 ? conn.a.o.pts[conn.a.i] : conn.b.o.pts[conn.b.i];
		const hue = lerp(conn.a.o.pts[conn.a.i].z, conn.b.o.pts[conn.b.i].z, random()); // random hue betwenn the connection nodes
		colorMode(HSB);
		fill(hue, 75, 75, random()*0.5);
		const msgStr = "incomplete";
		let startPos = floor(random(msgStr.length));
		let endPos = min(msgStr.length, startPos + floor(random(msgStr.length)));
		let displayStr = msgStr.substring(startPos, endPos); // msgStr.charAt(floor(random(msgStr.length)))
		text(displayStr, random(width), random(height));
		pop();
	}

	// display origins
	for (let o of origins) {
		o.update();
		o.show();
	}

	// display connections
	// const drawConns = shuffle(connections).splice(floor(random(connections.length)));
	for (let c of connections) { // drawConns
		c.update();
		c.show();
		// if (random()<0.1) break; // incomplete array
	}

	// display stars
	if (true) {
		push()
		fill(255)
		noStroke()
		for (let i = 0; i < 10; i++) {
			circle(random(width), random(height), random(1,3));
		}
		pop();
	}
}

class Origin {
	constructor(x, y, r, n, hueStart = 0, hueDelta = 360) {
		this.x = x;
		this.y = y; 
		this.r = r;

		this.n = n;
		this.a = 0;
		this.da = TWO_PI / n;

		this.pts = Array(n);
		for (let i = 0, a = 0; i < this.n; i++, a += this.da) {
			this.pts[i] = createVector(0, 0, (hueStart + a / TWO_PI * (hueDelta)) % 360); // {x, y};
		}
		this.update();
		// console.log(this);
	}

	update() {
		let a = this.a += 0.01;
		// for (let p of this.pts) {
		for (let i = 0; i < this.n; i++) {
			const x = cos(a) * this.r + this.x;
			const y = sin(a) * this.r + this.y;
			this.pts[i].set(x, y, this.pts[i].z); // {x, y};
			a += this.da;
		}
	}

	show() {
		push();
		stroke(255)
		noFill()

		// circle(this.x, this.y, this.r + this.r);

		colorMode(HSB);
		noStroke();
		for (let p of this.pts) {
			fill(p.z, 75, 75);
			// circle(p.x, p.y, this.r * 0.1);
		}

		pop();
	}
}

